CREATE DATABASE IF NOT EXISTS campuspass_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campuspass_portal;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs; DROP TABLE IF EXISTS login_attempts; DROP TABLE IF EXISTS checkins; DROP TABLE IF EXISTS registrations; DROP TABLE IF EXISTS events; DROP TABLE IF EXISTS admin_users; DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,mobile VARCHAR(25) NOT NULL,password_hash VARCHAR(255) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','event_admin','checkin_staff') NOT NULL DEFAULT 'checkin_staff',is_active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,category VARCHAR(80) NOT NULL DEFAULT 'Other',description TEXT NOT NULL,venue VARCHAR(200) NOT NULL,event_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NULL,capacity INT UNSIGNED NOT NULL,organiser VARCHAR(160) NULL,rules TEXT NULL,image_url VARCHAR(1000) NULL,status ENUM('draft','published','closed','cancelled') NOT NULL DEFAULT 'draft',registration_start DATETIME NULL,registration_end DATETIME NULL,created_by BIGINT UNSIGNED NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,INDEX idx_events_date_status(event_date,status),INDEX idx_events_category(category),CONSTRAINT fk_events_admin FOREIGN KEY(created_by) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,event_id BIGINT UNSIGNED NOT NULL,registration_code VARCHAR(40) NOT NULL UNIQUE,entry_code VARCHAR(24) NOT NULL UNIQUE,qr_token CHAR(48) NOT NULL UNIQUE,status ENUM('valid','cancelled') NOT NULL DEFAULT 'valid',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_registration_user_event(user_id,event_id),INDEX idx_registration_event_status(event_id,status),INDEX idx_registration_user(user_id),INDEX idx_registration_code(registration_code),INDEX idx_entry_code(entry_code),CONSTRAINT fk_reg_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_reg_event FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE checkins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,registration_id BIGINT UNSIGNED NOT NULL UNIQUE,event_id BIGINT UNSIGNED NOT NULL,staff_admin_id BIGINT UNSIGNED NOT NULL,entry_code VARCHAR(24) NOT NULL,checked_in_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_checkin_event_time(event_id,checked_in_at),CONSTRAINT fk_checkin_registration FOREIGN KEY(registration_id) REFERENCES registrations(id) ON DELETE RESTRICT,CONSTRAINT fk_checkin_event FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE RESTRICT,CONSTRAINT fk_checkin_staff FOREIGN KEY(staff_admin_id) REFERENCES admin_users(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE login_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_address VARCHAR(64) NOT NULL,email VARCHAR(190) NOT NULL,success TINYINT(1) NOT NULL DEFAULT 0,attempted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_login_attempts(ip_address,attempted_at,success)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details TEXT NULL,ip_address VARCHAR(64) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_time(created_at),INDEX idx_audit_admin(admin_id),CONSTRAINT fk_audit_admin FOREIGN KEY(admin_id) REFERENCES admin_users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

